//! E3c-0 — the C2a render gate (design 8.1). The Coasys bundle rendered by
//! the Rust app at the ten captured routes, theme `coasys--glow`, viewport
//! 1440x900: the resolved tree compared byte-equal and the painted frame
//! compared pixel-tolerant against checked-in baselines. Every E3c task
//! that can change rendering must keep this green; a task that moves a
//! route stops, names it and why in its PR, and waits for Lal (8.1).
//!
//! Baselines and their provenance — never regenerated by a later task:
//!
//! - `tests/coasys/<route>.tree.json` — generated from `d43118cf3`
//!   (`port/split`, before E3c-1/E3c-3), by the `we-app dump` construction:
//!   `StoreBag::from_snapshot` + `Runtime::app` + the registry `$`-type
//!   gate + `StaticHost`, settled, printed as `normal_form` pretty JSON.
//!   `d43118cf3` predates route captures (`OfflineData::from_route`), so
//!   the flat snapshot tables are the only construction both commits share;
//!   the tree half below uses the same one so the diff isolates code
//!   changes. A route that could not render at `d43118cf3` has that
//!   failure recorded in NOTES-e3c-0.md instead of a baseline.
//!
//!   Advanced once, with Lal's approval, to the output of `fd6f433f9`
//!   (port/m1-fix-a, approved at 96418f442): that merge wraps the app
//!   root's content subtree in the `meta.frame` band (`Column` with
//!   `position: fixed; left: 72px; top: 0px; width: calc(100vw - 72px);
//!   height: calc(100vh - 0px); overflowY: auto; bg: page`). For all ten
//!   routes the root, its first child and the wrapped subtree are
//!   byte-identical to the `d43118cf3` output; see the baseline commit.
//!
//! - `tests/snapshots/coasys_<route>.png` + `coasys_tree_panel.png` —
//!   recorded from `2a9edd244` (the E3c-0 base: E3c-1, E3c-3, the theme
//!   rounds and the fonts round merged) in record mode.
//!
//! The re-record rule: a visual round re-records only the routes it means
//! to change, in its own commit named `baseline: <routes>: <reason>`, and
//! lists the routes and the reason in its notes. E3c refactor tasks must
//! not move a pixel; a tree or pixel change that is not the task's stated
//! purpose is a stop, not an update.
//!
//! Record mode — the only path that writes baselines — is the operator's
//! two flags together, e.g.
//! `WE_RECORD_COASYS=1 UPDATE_SNAPSHOTS=force cargo test --locked -p we-app --test coasys_render -- pixel_index`.
//! The gate *checks* `UPDATE_SNAPSHOTS`, never sets it — `set_var` from
//! one test thread races the `getenv`s of every parallel test (and is
//! `unsafe` under edition 2024). So: a verify run refuses an inherited
//! update value instead of overwriting it, and a record run must export
//! `force` itself (Lal P3).
//!
//! Clock: every pixel harness pins `we_egui`'s injected clock to
//! `PINNED_NOW` — `we-timestamp`'s relative text and `we-date-picker`'s
//! "today" then read the pin, not the day the test happens to run on.
//!
//! Data: `bundles/coasys.bundle.json` + `fixtures/coasys/snapshot.json`.
//! The snapshot's sha256 is asserted before anything reads it, so capture
//! bytes cannot drift under the test.

#[path = "support/gpu.rs"]
mod gpu;

use std::path::PathBuf;
use std::sync::Arc;

use egui::Vec2;
use egui_kittest::kittest::Queryable;
use egui_kittest::{Harness, SnapshotOptions, SnapshotResults};
use serde_json::Value as Json;
use sha2::{Digest, Sha256};
use we_app::gallery::load_theme_set;
use we_app::{RendererApp, Shell};
use we_egui::Registry;
use we_screen::{ScreenSchema, ScreenState};
use we_session::{Session, Tick};
use we_template::{normal_form, AppSpec, Bundle, ResolvedNode, RootSpec, SchemaNode, StoreBag};

const BUNDLE: &str = include_str!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../../bundles/coasys.bundle.json"
));
const SNAPSHOT: &str = include_str!("../../fixtures/coasys/snapshot.json");

/// sha256 of `fixtures/coasys/snapshot.json` — asserted before any read.
const SNAPSHOT_SHA256: &str = "3119d84aaaddc4eee363493f427eb0d3d9a832cf197fb8ccc91292d30531b0b3";

/// The theme C2a recorded (`meta.captureTheme` and every route's `theme`).
/// Its token table is the suffix after `--` — `coasys--glow` → `glow`.
const CAPTURE_THEME: &str = "coasys--glow";

/// The ten routes C2a recorded, in the recording's order.
const ROUTES: [&str; 10] = [
    "index",
    "workflows",
    "channels",
    "channel-design",
    "calls",
    "call",
    "people",
    "dna",
    "person",
    "about",
];

/// 1440x900 logical px, `pixels_per_point` 1.0 — the pinned viewport.
const W: f32 = 1440.0;
const H: f32 = 900.0;

/// `poll → resolve` may run at most this many rounds before the test
/// refuses — the design's bound (8.1), generous for a synchronous source.
const MAX_SETTLE_ROUNDS: u32 = 8;

/// Image decode is not session work: the offline fixture's image URIs can
/// stay pending forever, so decode waits on wall-clock sleeps, never on
/// extra steps — the step count (and with it `i.time`) stays deterministic.
const IMAGE_DRAIN_SLEEPS: u32 = 150;

/// The instant every pixel harness pins `we_egui::pin_now` to — epoch
/// seconds of **2025-10-07T00:00:00Z**, the morning after the fixture's
/// newest stamp (`2025-10-06T15:00:00Z`, inside the recorded week;
/// `snapshot.json`'s `meta` records no capture date, the fixture epoch is
/// `2025-10-01`). Without it, `we-timestamp` relative text drifts with the
/// wall clock and the PNG baselines go stale on their own (Lal F2).
const PINNED_NOW: f64 = 1_759_795_200.0;

/// Record mode's env flag — the ONLY way these tests write baselines.
const RECORD_ENV: &str = "WE_RECORD_COASYS";

fn renderer_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("..")
}

/// The recording, parsed — but only after its bytes check out, so a drifted
/// capture fails on the sha before any tree can be built from it.
fn truth() -> Json {
    let digest = format!("{:x}", Sha256::digest(SNAPSHOT.as_bytes()));
    assert_eq!(
        digest, SNAPSHOT_SHA256,
        "fixtures/coasys/snapshot.json sha256 drifted: expected {SNAPSHOT_SHA256}, got {digest}"
    );
    serde_json::from_str(SNAPSHOT).expect("snapshot parses")
}

/// `routes.<id>` — its `rust` path (params included) and its recorded
/// theme, both asserted rather than skipped when absent.
fn route<'a>(truth: &'a Json, id: &str) -> &'a Json {
    let route = truth
        .get("routes")
        .and_then(|r| r.get(id))
        .unwrap_or_else(|| panic!("snapshot has no routes.{id}"));
    let path = route
        .get("rust")
        .and_then(|p| p.as_str())
        .unwrap_or_else(|| panic!("routes.{id}.rust is not a path"));
    // `rust` carries the route's params in its query; the recorded
    // `params` must agree — a drifted capture fails here, not later.
    let params = route
        .get("params")
        .and_then(|p| p.as_object())
        .unwrap_or_else(|| panic!("routes.{id}.params is not a table"));
    let query = we_screen::parse_query(path.split_once('?').map(|(_, q)| q).unwrap_or(""));
    assert_eq!(
        query.len(),
        params.len(),
        "routes.{id}: query in `rust` and recorded `params` disagree"
    );
    for (key, value) in params {
        let Some(value) = value.as_str() else {
            panic!("routes.{id}.params.{key} is not a string")
        };
        assert_eq!(
            query.get(key).map(String::as_str),
            Some(value),
            "routes.{id}: param {key} differs between `rust` and `params`"
        );
    }
    let theme = route
        .get("theme")
        .and_then(|t| t.as_str())
        .unwrap_or_else(|| panic!("routes.{id}.theme is missing — a skip is not allowed"));
    assert_eq!(
        theme, CAPTURE_THEME,
        "routes.{id}.theme drifted from the capture theme"
    );
    route
}

/// `coasys--glow`'s token table, loaded the way the gallery loads themes.
/// A missing table is a failure, not a fallback.
fn capture_theme() -> we_style::Theme {
    let set = load_theme_set();
    let table = CAPTURE_THEME
        .rsplit_once("--")
        .map(|(_, t)| t)
        .expect("capture theme names its table");
    let (theme, fell_back) = set.theme(table);
    assert!(
        !fell_back,
        "no recorded token table for {table} ({CAPTURE_THEME})"
    );
    theme.clone()
}

/// The app at `routes.<id>.rust`: `we-app dump`'s construction — the flat
/// snapshot stores, the bundle's app root, the registry `$`-type gate and
/// the offline host, on a `Session` — the shape every frontend shares.
fn session_for(truth: &Json, id: &str) -> Session {
    let bag = Arc::new(StoreBag::from_snapshot(truth).expect("snapshot stores load"));
    let bundle = Bundle::parse(BUNDLE).expect("bundle parses");
    let spec = AppSpec {
        bundle: bundle.name.clone().into(),
        app: bundle.app.clone(),
        template: bundle.templates.as_deref().and_then(|t| t.first()).cloned(),
        pages: bundle.pages.clone().unwrap_or_default(),
        boot: bundle.boot_screen.clone(),
    };
    let screen = ScreenState::desktop(
        ScreenSchema {
            pages: bundle
                .pages
                .as_deref()
                .unwrap_or_default()
                .iter()
                .map(|p| p.id.clone())
                .collect(),
            ..ScreenSchema::default()
        },
        route(truth, id)["rust"].as_str().unwrap(),
    );
    let types: std::collections::HashSet<&'static str> =
        Registry::with_builtins().type_names().collect();
    Session::offline(RootSpec::App(Box::new(spec)), bag, screen)
        .with_dollar_types(move |ty| types.contains(ty))
}

/// The same, as a `RendererApp` — the pixel half renders through
/// `frame_body` so `we_egui::layout` and `paint` do what the window's do.
fn app_for(truth: &Json, id: &str) -> RendererApp {
    let placeholder: SchemaNode =
        serde_json::from_value(serde_json::json!({ "type": "Column" })).unwrap();
    let session = session_for(truth, id);
    // `RendererApp::new` builds a single-schema session; the app root needs
    // the `RootSpec::App` session, so it is swapped in — the shape `m1a`
    // and `coasys_shots` use.
    let mut app = RendererApp::new(
        placeholder,
        "coasys",
        Arc::new(StoreBag::new()),
        ScreenState::desktop(ScreenSchema::default(), "/"),
        Registry::with_builtins(),
    );
    app.session = session;
    app.theme = capture_theme();
    app
}

/// The gate's settle loop (8.1): `poll → resolve` until `poll` reports
/// quiet — at most `MAX_SETTLE_ROUNDS` rounds, a failure past that. Quiet
/// is `Tick::default()`: no arrivals and nothing dirty.
fn settle(session: &mut Session) -> Arc<ResolvedNode> {
    let mut resolved = session.resolve();
    for _ in 0..MAX_SETTLE_ROUNDS {
        if session.poll() == Tick::default() {
            return resolved;
        }
        resolved = session.resolve();
    }
    panic!("the session did not settle in {MAX_SETTLE_ROUNDS} poll→resolve rounds");
}

/// The frame-level settle: a harness `step` is `frame_body` — resolve +
/// layout + paint — and `poll` is the quiet signal between steps, the same
/// `poll → resolve` loop `settle` runs. Image decode gets a bounded
/// wall-clock drain afterwards so the step count stays deterministic —
/// then two checks (Lal F4): the drain must actually finish (pending
/// images are a failure, not a deadline the test waves through), and the
/// frame the drain produced must itself be quiet, so the captured pixels
/// are a settled frame, not one whose work is still queued.
fn settle_frame(harness: &mut Harness<'_, RendererApp>) {
    for _ in 0..MAX_SETTLE_ROUNDS {
        harness.step();
        if harness.state_mut().session.poll() == Tick::default() {
            drain_images_or_fail(&harness.ctx);
            harness.step();
            assert_quiet(&mut harness.state_mut().session);
            return;
        }
    }
    panic!("the frame did not settle in {MAX_SETTLE_ROUNDS} poll→step rounds");
}

/// `settle_frame` for the `Shell` — the same `poll → step` loop, over the
/// shell's panel session.
fn settle_frame_shell(harness: &mut Harness<'_, Shell>) {
    for _ in 0..MAX_SETTLE_ROUNDS {
        harness.step();
        if harness.state_mut().panel.session.poll() == Tick::default() {
            drain_images_or_fail(&harness.ctx);
            harness.step();
            assert_quiet(&mut harness.state_mut().panel.session);
            return;
        }
    }
    panic!("the frame did not settle in {MAX_SETTLE_ROUNDS} poll→step rounds");
}

/// The bounded wall-clock image drain: sleeps while any loader reports
/// pending, then a hard fail — a fixture image that never landed passing
/// as its placeholder is a silent partial (Lal F4). egui's loader API
/// reports pending per loader, not per URI, so the failure names loaders.
fn drain_images_or_fail(ctx: &egui::Context) {
    for _ in 0..IMAGE_DRAIN_SLEEPS {
        if !ctx.has_pending_images() {
            return;
        }
        std::thread::sleep(std::time::Duration::from_millis(20));
    }
    let loaders = ctx.loaders();
    let mut pending: Vec<String> = loaders
        .image
        .lock()
        .iter()
        .filter(|l| l.has_pending())
        .map(|l| l.id().to_string())
        .collect();
    pending.extend(
        loaders
            .bytes
            .lock()
            .iter()
            .filter(|l| l.has_pending())
            .map(|l| l.id().to_string()),
    );
    panic!(
        "images still pending after {}ms — loaders: {pending:?}",
        u64::from(IMAGE_DRAIN_SLEEPS) * 20
    );
}

/// The last frame's quiet check — work it queued is a settle failure,
/// not a pass.
fn assert_quiet(session: &mut Session) {
    let tick = session.poll();
    assert_eq!(
        tick,
        Tick::default(),
        "the final frame queued work — the captured frame is not settled"
    );
}

/// Whether this run verifies or records — the only two env combinations
/// the gate accepts.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum SnapshotPolicy {
    /// `UPDATE_SNAPSHOTS` absent or a kittest test value — kittest compares.
    Verify,
    /// `WE_RECORD_COASYS` truthy AND `UPDATE_SNAPSHOTS=force` exported —
    /// the operator set kittest's update-all flag; a deliberate rewrite.
    Record,
}

/// The env decision — check, never write (Lal P3). `std::env::set_var`
/// from one test thread while others `getenv` — kittest's
/// `Mode::from_env` reads `UPDATE_SNAPSHOTS` inside every `snapshot`
/// call — is the glibc setenv/getenv race, `unsafe` under edition 2024.
/// A `Once` would only narrow the window, not close it, so a conflicting
/// env is a hard fail naming the fix instead of a silent overwrite.
/// Verify needs no write at all: absent or a test value already runs
/// kittest's `Test` mode. Pure so the policy is testable without
/// touching process env.
fn snapshot_policy(record: Option<&str>, update: Option<&str>) -> Result<SnapshotPolicy, String> {
    let record = matches!(record, Some("1" | "on" | "true" | "force"));
    match (record, update) {
        (true, Some("force")) => Ok(SnapshotPolicy::Record),
        (true, other) => Err(format!(
            "{RECORD_ENV} asks to re-record baselines, but the gate never writes \
             process env — export UPDATE_SNAPSHOTS=force yourself (found {other:?})"
        )),
        (false, None | Some("false" | "0" | "no" | "off")) => Ok(SnapshotPolicy::Verify),
        (false, Some(value)) => Err(format!(
            "inherited UPDATE_SNAPSHOTS={value:?} would turn this verify run into a \
             baseline rewrite — unset it, or record on purpose with \
             {RECORD_ENV}=1 UPDATE_SNAPSHOTS=force"
        )),
    }
}

/// Check the env before `harness.snapshot` reads `UPDATE_SNAPSHOTS` —
/// reads only, never writes.
fn check_snapshot_policy() {
    let record = std::env::var(RECORD_ENV).ok();
    let update = std::env::var("UPDATE_SNAPSHOTS").ok();
    if let Err(message) = snapshot_policy(record.as_deref(), update.as_deref()) {
        panic!("{message}");
    }
}

/// `init_host` plus the clock pin — every pixel harness's context setup.
fn gate_context_setup(ctx: &egui::Context) {
    we_app::init_host(ctx);
    we_egui::pin_now(ctx, Some(PINNED_NOW));
}

/// The pinned raster harness (the gallery's `pinned_harness` policy):
/// vendored fonts, 1px-per-point, the CPU-preferred wgpu adapter, dify's
/// raw-YIQ `threshold 0.05` (any ≥1-level channel change fails a non-AA
/// pixel) with an 8-px changed-area budget. The accessibility audit is off
/// — these are pictures, and the bundle's unnamed buttons are recorded.
fn pixel_harness(app: RendererApp) -> Harness<'static, RendererApp> {
    Harness::builder()
        .renderer(gpu::serial())
        .with_size(Vec2::new(W, H))
        .with_pixels_per_point(1.0)
        .with_context_setup(gate_context_setup)
        // The builder's glyph policy lands after `context_setup`, so the
        // production `init_host`'s Tofu is restated here — recorded data
        // must not panic the renderer on a missing glyph.
        .allow_missing_glyphs()
        .with_accessibility_check(false)
        .wgpu()
        .with_options(SnapshotOptions::new().threshold(0.05).max_failed_pixels(8))
        .build_ui_state(|ui, app: &mut RendererApp| app.frame_body(ui), app)
}

/// Where a failed tree compare writes what it actually got, for the diff
/// in NOTES or a review — `crates/renderer/target/`, like `coasys_shots`.
fn write_actual(id: &str, actual: &str) {
    let dir = renderer_dir().join("target/coasys-render");
    std::fs::create_dir_all(&dir).unwrap();
    std::fs::write(dir.join(format!("{id}.tree.actual.json")), actual).unwrap();
}

/// First difference between baseline and actual, for the assert message.
fn first_diff(expected: &str, actual: &str) -> String {
    for (i, (e, a)) in expected.lines().zip(actual.lines()).enumerate() {
        if e != a {
            return format!("line {}:\n  baseline: {e}\n  actual:   {a}", i + 1);
        }
    }
    let (el, al) = (expected.lines().count(), actual.lines().count());
    format!(
        "same for {} lines; baseline has {el}, actual has {al}",
        el.min(al)
    )
}

fn tree_gate(id: &str, expected: &str) {
    let truth = truth();
    let mut session = session_for(&truth, id);
    let root = settle(&mut session);
    let actual = format!(
        "{}\n",
        serde_json::to_string_pretty(&normal_form(&root)).unwrap()
    );
    if actual != expected {
        write_actual(id, &actual);
        panic!(
            "routes.{id} tree differs from the d43118cf3 baseline ({})\n\
             actual written to target/coasys-render/{id}.tree.actual.json",
            first_diff(expected, &actual)
        );
    }
}

fn pixel_gate(id: &str, results: &mut SnapshotResults) {
    check_snapshot_policy();
    let truth = truth();
    let app = app_for(&truth, id);
    let mut harness = pixel_harness(app);
    settle_frame(&mut harness);
    harness.snapshot(format!("coasys_{id}"));
    results.extend_harness(&mut harness);
}

macro_rules! tree_tests {
    ($($(#[$m:meta])* $name:ident => $route:literal),* $(,)?) => {
        $(#[test]
        $(#[$m])*
        fn $name() {
            let expected = std::fs::read_to_string(concat!(
                env!("CARGO_MANIFEST_DIR"),
                "/tests/coasys/",
                $route,
                ".tree.json"
            ))
            .unwrap_or_else(|e| {
                panic!("baseline tests/coasys/{}.tree.json: {e}", $route)
            });
            tree_gate($route, &expected);
        })*
    };
}

/// The snapshot's sha256, first — a drifted capture fails here before any
/// tree or pixel is built from it.
#[test]
fn snapshot_sha256_is_pinned() {
    let digest = format!("{:x}", Sha256::digest(SNAPSHOT.as_bytes()));
    assert_eq!(digest, SNAPSHOT_SHA256);
}

/// `meta.captureTheme` is `coasys--glow`, and every captured route's
/// `theme` agrees — a missing theme is a failure, not a skip (8.1).
#[test]
fn capture_theme_is_glow() {
    let truth = truth();
    let meta_theme = truth["meta"]["captureTheme"]
        .as_str()
        .expect("meta.captureTheme is recorded");
    assert_eq!(meta_theme, CAPTURE_THEME);
    for id in ROUTES {
        route(&truth, id);
    }
    assert_eq!(capture_theme().id.as_ref(), "glow");
}

tree_tests! {
    tree_index => "index",
    tree_workflows => "workflows",
    tree_channels => "channels",
    tree_channel_design => "channel-design",
    tree_calls => "calls",
    tree_call => "call",
    tree_people => "people",
    tree_dna => "dna",
    tree_person => "person",
    tree_about => "about",
}

macro_rules! pixel_tests {
    ($($name:ident => $route:literal),* $(,)?) => {
        $(#[test]
        fn $name() {
            let mut results = SnapshotResults::new();
            pixel_gate($route, &mut results);
            results.unwrap();
        })*
    };
}

pixel_tests! {
    pixel_index => "index",
    pixel_channel_design => "channel-design",
    pixel_call => "call",
    pixel_workflows => "workflows",
    pixel_about => "about",
}

/// The native tree panel — what `we-app --offline` puts in its side panel
/// today (`Shell` over the bundle's `tree` panel schema) — at `index`, on
/// the same flat snapshot the window's `--snapshot` loads.
#[test]
fn tree_panel() {
    check_snapshot_policy();
    let truth = truth();
    let bundle = Bundle::parse(BUNDLE).expect("bundle parses");
    let schema: SchemaNode = serde_json::from_value(
        bundle.templates.as_deref().unwrap()[0]
            .meta
            .get("panels")
            .unwrap()
            .as_array()
            .unwrap()
            .iter()
            .find(|p| p.get("id").and_then(|i| i.as_str()) == Some("tree"))
            .and_then(|p| p.get("node"))
            .cloned()
            .unwrap(),
    )
    .expect("tree panel parses");
    let bag = Arc::new(StoreBag::from_snapshot(&truth).expect("snapshot stores load"));
    let mut panel = RendererApp::new(
        schema,
        "tree",
        bag,
        ScreenState::desktop(
            ScreenSchema::default(),
            route(&truth, "index")["rust"].as_str().unwrap(),
        ),
        Registry::with_builtins(),
    );
    panel.theme = capture_theme();
    let shell = Shell { panel };
    let mut harness = Harness::builder()
        .renderer(gpu::serial())
        .with_size(Vec2::new(W, H))
        .with_pixels_per_point(1.0)
        .with_context_setup(gate_context_setup)
        .allow_missing_glyphs()
        .with_accessibility_check(false)
        .wgpu()
        .with_options(SnapshotOptions::new().threshold(0.05).max_failed_pixels(8))
        .build_ui_state(|ui, shell: &mut Shell| shell.frame_body(ui), shell);
    settle_frame_shell(&mut harness);
    harness.snapshot("coasys_tree_panel");
    let mut results = SnapshotResults::new();
    results.extend_harness(&mut harness);
    results.unwrap();
}

/// The env policy is a pure decision — and never a write (Lal P3).
/// Verify accepts `UPDATE_SNAPSHOTS` absent or a kittest test value and
/// refuses any other inherited value rather than overwrite it; record
/// accepts only `WE_RECORD_COASYS` and `UPDATE_SNAPSHOTS=force` exported
/// together.
#[test]
fn snapshot_policy_checks_env_and_never_writes() {
    use SnapshotPolicy::*;
    assert_eq!(snapshot_policy(None, None), Ok(Verify));
    for off in ["false", "0", "no", "off"] {
        assert_eq!(snapshot_policy(None, Some(off)), Ok(Verify));
    }
    for update in ["1", "true", "yes", "on", "force", "nonsense"] {
        assert!(snapshot_policy(None, Some(update)).is_err());
    }
    assert_eq!(snapshot_policy(Some("1"), Some("force")), Ok(Record));
    for other in [None, Some("1"), Some("off"), Some("nonsense")] {
        assert!(snapshot_policy(Some("1"), other).is_err());
    }
}

/// The pinned clock is real, not decorative (Lal F2): re-pin "now" to an
/// absurd instant — the epoch — and the relative text `we-timestamp`
/// paints moves with it. Under the fixture's own week the same widgets
/// read "9h ago"/"Nd ago" (narrow style, as `Intl.RelativeTimeFormat`
/// writes it); under 1970 they read "in 56y".
#[test]
fn pinned_clock_moves_timestamp_text() {
    let truth = truth();
    let app = app_for(&truth, "index");
    let mut harness = pixel_harness(app);
    we_egui::pin_now(&harness.ctx, Some(0.0)); // 1970-01-01T00:00:00Z
    settle_frame(&mut harness);
    // Panics when no painted node carries the absurd pin's text — under
    // the wall clock or `PINNED_NOW` this label cannot appear.
    harness.get_by_label("in 56y");
}
